// LLM gateway (LiteLLM on the node) admin client: one virtual key per tenant,
// carrying the tenant's monthly budget. The key value is generated by us and
// kept in the Secret table, so every call here is idempotent.

export type KeyInfo = {
  spend: number;
  max_budget: number | null;
  budget_reset_at?: string | null;
  blocked?: boolean | null;
};

export class LlmGateway {
  constructor(
    private readonly baseUrl: string,
    private readonly masterKey: string,
  ) {}

  private async request<T>(method: string, path: string, body?: unknown): Promise<{ status: number; data: T }> {
    const res = await fetch(`${this.baseUrl}${path}`, {
      method,
      headers: { Authorization: `Bearer ${this.masterKey}`, "Content-Type": "application/json" },
      body: body === undefined ? undefined : JSON.stringify(body),
      signal: AbortSignal.timeout(30_000),
    });
    const text = await res.text();
    const data = (text ? JSON.parse(text) : undefined) as T;
    if (!res.ok && res.status !== 404) throw new Error(`LLM gateway ${method} ${path} -> ${res.status}: ${text.slice(0, 500)}`);
    return { status: res.status, data };
  }

  async info(key: string): Promise<KeyInfo | undefined> {
    try {
      const { status, data } = await this.request<{ info?: KeyInfo }>("GET", `/key/info?key=${encodeURIComponent(key)}`);
      return status === 404 ? undefined : data.info;
    } catch (err) {
      // LiteLLM answers an unknown key with 400/401 on some versions.
      if (/-> (400|401)/.test((err as Error).message)) return undefined;
      throw err;
    }
  }

  /** Creates or updates the tenant key: budget per month, only the assistant model. */
  async ensureTenantKey(opts: { key: string; slug: string; tenantId: string; maxBudgetUsd: number; warnAt: number }) {
    const settings = {
      key_alias: `tenant-${opts.slug}`,
      max_budget: opts.maxBudgetUsd,
      soft_budget: Math.round(opts.maxBudgetUsd * opts.warnAt * 100) / 100,
      budget_duration: "1mo",
      models: ["assistant"],
      metadata: { tenant_id: opts.tenantId },
    };
    const existing = await this.info(opts.key);
    if (!existing) {
      await this.request("POST", "/key/generate", { key: opts.key, ...settings });
      return;
    }
    // budget_duration is left as is, so the monthly reset date doesn't move.
    const { budget_duration: _keep, ...update } = settings;
    await this.request("POST", "/key/update", { key: opts.key, ...update });
    if (existing.blocked) await this.request("POST", "/key/unblock", { key: opts.key });
  }

  /** Suspended tenant or assistant unbooked: no more requests, spend kept. */
  async block(key: string) {
    if (await this.info(key)) await this.request("POST", "/key/block", { key });
  }

  async delete(key: string) {
    if (await this.info(key)) await this.request("POST", "/key/delete", { keys: [key] });
  }
}
